const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal'), authRoot=$('#auth-root'), workspace=$('#workspace-shell');
let savedDraft={};try{savedDraft=JSON.parse(localStorage.getItem('eval-draft')||'{}');}catch{}
const S={auth:null,csrfToken:'',authEpoch:0,authScreen:'',authMessage:'',authLoading:false,passwordScreen:false,boot:null,draft:savedDraft,filter:'all',search:'',task:null,generated:null,preflight:null,preflightKey:'',dirty:false};
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#${n}"/></svg>`;
const button=(text,action,primary=false,extra='')=>`<button type="button" class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,url,primary=false)=>`<a class="button ${primary?'primary':''}" href="#${url}">${text}</a>`;
const pct=v=>v==null?'—':`${(v*100).toFixed(1)}%`;
const date=v=>v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
const statusNames={running:'运行中',stopping:'正在停止',paused:'已暂停',stopped:'已停止',interrupted:'运行中断',completed:'已完成',completed_with_errors:'部分失败',pending:'等待中',calling:'调用Agent',judging:'评分中',done:'已评分',error:'失败'};
function workspaceReady(){return Boolean(S.auth?.authenticated&&!S.auth.user?.mustChangePassword&&!S.passwordScreen);}
function authError(message,code='UNAUTHENTICATED'){return Object.assign(new Error(message),{code,silent:true});}
function clearWorkspace({clearDraft=false}={}){for(const key of ['boot','task','dataset','generated','reviewRow','caseEditing','preflight'])S[key]=null;S.preflightKey='';S.dirty=false;S.renderedHash=null;S.filter='all';S.search='';clearTimeout(S.checkTimer);clearTimeout(S.toastTimer);if(clearDraft){S.draft=Object.fromEntries(['datasetId','agentId','rubricId','mode','answerColumn'].filter(k=>S.draft[k]).map(k=>[k,S.draft[k]]));localStorage.removeItem('eval-draft');}modal.close();modal.replaceChildren();app.replaceChildren();$('#account-menu').open=false;$('#account-menu').replaceChildren();$('#toast').classList.remove('show');$('#toast').textContent='';workspace.hidden=true;}
function setAuthState(data){S.authEpoch++;S.auth=data?.authenticated&&data.user?{authenticated:true,user:data.user}:{authenticated:false,user:null};S.csrfToken=S.auth.authenticated&&typeof data.csrfToken==='string'?data.csrfToken:'';S.authScreen='';S.authMessage='';if(!S.auth.authenticated){S.passwordScreen=false;clearWorkspace({clearDraft:true});}else if(S.auth.user.mustChangePassword){S.passwordScreen=true;clearWorkspace();}}
function expireSession(message='登录已过期，请重新登录。'){const dirty=S.dirty;setAuthState({authenticated:false});S.authMessage=message+(dirty?'未保存的修改已清除。':'');renderAuthScreen(true);}
function requirePasswordChange(){S.authEpoch++;if(S.auth?.user)S.auth.user.mustChangePassword=true;S.passwordScreen=true;clearWorkspace();S.authScreen='';renderAuthScreen(true);}
function passwordInput(name,label,{autocomplete='current-password',minLength,maxLength=128}={}){return `<div class="field"><label class="field-label" for="${name}">${label}<span class="required-marker" aria-hidden="true"> *</span><span class="sr-only">（必填）</span></label><div class="password-control"><input id="${name}" name="${name}" type="password" required aria-required="true" autocomplete="${autocomplete}" ${minLength?`minlength="${minLength}"`:''} maxlength="${maxLength}" ${name==='newPassword'?'aria-describedby="password-rules"':''}><button type="button" class="password-toggle" data-action="toggle-password" data-target="${name}" aria-controls="${name}" aria-label="显示${label}" aria-pressed="false">显示</button></div></div>`;}
function authBrand(){return `<div class="auth-brand"><div class="brandmark" aria-hidden="true">${icon('layers')}</div><div><strong>Eval Studio</strong><span>Agent 评测工作空间</span></div></div>`;}
function authFrame(content){return `<div class="auth-layout">${authBrand()}<section class="auth-card">${content}</section><p class="auth-footer">本地管理员工作空间</p></div>`;}
function loginScreen(){return authFrame(`<h1 id="auth-title" tabindex="-1">登录工作空间</h1><p class="auth-intro">首次登录请使用管理员提供的初始密码。</p>${S.authMessage?`<div class="auth-notice" role="status">${e(S.authMessage)}</div>`:''}<form id="login-form"><div class="field"><label class="field-label" for="username">管理员账号<span class="required-marker" aria-hidden="true"> *</span></label><input id="username" name="username" value="admin" autocomplete="username" autocapitalize="none" spellcheck="false" maxlength="128" required aria-required="true"></div>${passwordInput('password','密码')}${errorSlot()}<button type="submit" class="button primary auth-submit">登录</button></form>`);}
function passwordScreen(){const forced=Boolean(S.auth?.user?.mustChangePassword);return authFrame(`<span class="auth-account-label">${e(S.auth?.user?.username||'admin')} · 管理员</span><h1 id="auth-title" tabindex="-1">${forced?'设置新的登录密码':'修改登录密码'}</h1><p class="auth-intro">${forced?'首次登录，请先更换初始密码。':'修改后将继续使用当前工作空间。'}</p><form id="password-form">${passwordInput('currentPassword',forced?'初始密码':'当前密码')}${passwordInput('newPassword','新密码',{autocomplete:'new-password',minLength:12})}<p id="password-rules" class="password-rules">12–128 个字符，与当前密码不同。</p>${passwordInput('confirmPassword','确认新密码',{autocomplete:'new-password',minLength:12})}${errorSlot()}<button type="submit" class="button primary auth-submit">${forced?'保存密码，进入工作空间':'保存新密码'}</button></form><div class="auth-secondary">${forced?button('退出登录','logout'):button('返回工作空间','cancel-password')}</div>`);}
function renderAuthScreen(force=false){const mode=S.auth?.authenticated?'password':S.auth===null?'checking':'login';workspace.hidden=true;authRoot.hidden=false;document.title=(mode==='password'?'修改密码':mode==='login'?'管理员登录':'正在连接')+' · Eval Studio';if(!force&&S.authScreen===mode&&authRoot.children.length)return;S.authScreen=mode;authRoot.innerHTML=mode==='login'?loginScreen():mode==='password'?passwordScreen():authFrame('<h1 id="auth-title" tabindex="-1">正在连接工作空间…</h1>');authRoot.querySelector('h1')?.focus({preventScroll:true});}
function updateAccount(){const user=S.auth?.user;if(!user)return;$('#account-menu').innerHTML=`<summary aria-label="账号：${e(user.username)}，管理员"><span class="account-avatar" aria-hidden="true">${e(user.username.slice(0,1).toUpperCase())}</span><span>${e(user.username)}</span><span class="account-chevron" aria-hidden="true">⌄</span></summary><div class="account-popover"><div class="account-identity"><strong>${e(user.username)}</strong><span>管理员</span></div><button type="button" data-action="change-password">修改密码</button><button type="button" data-action="logout">退出登录</button></div>`;}
function showWorkspace(){authRoot.hidden=true;authRoot.replaceChildren();S.authScreen='';workspace.hidden=false;updateAccount();}
async function initializeAuth(){if(S.authLoading)return;S.authLoading=true;const epoch=S.authEpoch;renderAuthScreen(true);try{const status=await api('/auth/status');if(epoch!==S.authEpoch)return;setAuthState(status);if(workspaceReady())await render();else renderAuthScreen(true);}catch(err){if(epoch!==S.authEpoch)return;S.authScreen='connection-error';workspace.hidden=true;authRoot.hidden=false;document.title='连接失败 · Eval Studio';authRoot.innerHTML=authFrame(`<h1 id="auth-title" tabindex="-1">暂时无法连接</h1><p class="auth-intro">${e(err.message)}</p>${button('重新连接','retry-auth',true)}`);}finally{S.authLoading=false;}}
async function submitAuth(form){const epoch=S.authEpoch;const submit=form.querySelector('[type="submit"]'),data=formData(form);submit.disabled=true;try{if(form.id==='login-form'){const status=await post('/auth/login',{username:data.username.trim(),password:data.password});if(epoch!==S.authEpoch)throw authError('登录状态已变化。','SESSION_CHANGED');form.reset();S.passwordScreen=false;setAuthState(status);}else{if(data.newPassword!==data.confirmPassword)throw Error('两次输入的新密码不一致。');if(data.newPassword.length<12||data.newPassword.length>128||!data.newPassword.trim())throw Error('新密码需要 12–128 个字符，不能仅为空格。');if(data.newPassword===data.currentPassword)throw Error('新密码不能与当前密码相同。');const status=await post('/auth/password',{currentPassword:data.currentPassword,newPassword:data.newPassword});if(epoch!==S.authEpoch)throw authError('登录状态已变化。','SESSION_CHANGED');form.reset();S.passwordScreen=false;setAuthState(status);}if(workspaceReady())await render();else renderAuthScreen(true);}catch(err){if(form.isConnected)formError(form,err);}finally{if(form.isConnected)submit.disabled=false;}}
async function logout(){try{await post('/auth/logout',{});}catch(err){if(err.code!=='UNAUTHENTICATED')throw err;}setAuthState({authenticated:false});renderAuthScreen(true);}

function status(s){const kind=['error','completed_with_errors'].includes(s)?'error':['paused','stopping','stopped','interrupted'].includes(s)?'paused':['running','calling','judging'].includes(s)?'running':['completed','done'].includes(s)?'pass':'pending';return `<span class="status ${kind}">${statusNames[s]||e(s)}</span>`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(path,options={}){const authPath=path.startsWith('/auth/'),method=String(options.method||'GET').toUpperCase(),epoch=S.authEpoch;if(!authPath&&!workspaceReady())throw authError('请先登录工作空间。');const headers={'Content-Type':'application/json',...options.headers};if(!['GET','HEAD','OPTIONS'].includes(method)&&S.csrfToken)headers['X-CSRF-Token']=S.csrfToken;const res=await fetch('/api'+path,{...options,method,credentials:'same-origin',headers});let body;try{body=await res.json();}catch{throw Error('服务响应异常。');}if(!authPath&&epoch!==S.authEpoch)throw authError('登录状态已变化，操作已结束。','SESSION_CHANGED');if(!res.ok){const code=body.code||(res.status===401&&!authPath?'UNAUTHENTICATED':'');if(code==='UNAUTHENTICATED'&&path!=='/auth/login'){expireSession();throw authError(body.error||'登录已过期，请重新登录。',code);}if(code==='PASSWORD_CHANGE_REQUIRED'){requirePasswordChange();throw authError(body.error||'请先修改初始密码。',code);}const error=Error(body.error||'请求失败。');error.code=code;throw error;}return body;}
const post=(path,data)=>api(path,{method:'POST',body:JSON.stringify(data)});
async function refresh(){S.boot=await api('/boot');}
const go=path=>{location.hash=path;};
function draft(patch){Object.assign(S.draft,patch);localStorage.setItem('eval-draft',JSON.stringify(S.draft));}
const route=()=>{const [p,q]=(location.hash.slice(1)||'/tasks').split('?');return {parts:p.split('/').filter(Boolean),query:new URLSearchParams(q||'')};};
function field(name,label,value='',type='text',hint='',required=false){const attr=`name="${e(name)}" id="${e(name)}" ${required?'required aria-required="true"':''} ${hint?`aria-describedby="${e(name)}-hint"`:''}`;let input;if(type==='textarea')input=`<textarea ${attr}>${e(value)}</textarea>`;else if(type==='checkbox')input=`<div class="selection"><input type="checkbox" ${attr} ${value?'checked':''}></div>`;else input=`<input ${attr} type="${type}" value="${e(value)}" ${type==='password'?'autocomplete="new-password"':''}>`;return `<div class="field ${type==='checkbox'?'checkbox-field':''}"><label class="field-label" for="${e(name)}">${e(label)}${required?'<span class="required-marker" aria-hidden="true"> *</span><span class="sr-only">（必填）</span>':''}</label>${input}${hint?`<small id="${e(name)}-hint">${e(hint)}</small>`:''}</div>`;}
function select(name,label,options,value,required=true){return `<div class="field"><label class="field-label" for="${e(name)}">${e(label)}${required?'<span class="required-marker" aria-hidden="true"> *</span><span class="sr-only">（必填）</span>':''}</label><select name="${e(name)}" id="${e(name)}" ${required?'required aria-required="true"':''}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(t)}</option>`;}).join('')}</select></div>`;}
function validConcurrency(value){const n=Number(value);return String(value).trim()!==''&&Number.isInteger(n)&&n>=1&&n<=50;}
function taskConcurrency(task){const value=task.concurrency??task.snapshot.agent?.concurrency??2;return validConcurrency(value)?Number(value):2;}
function sharedSession(mode,agent){return mode!=='existing'&&agent?.sessionMode==='dataset';}
function concurrencyHint(value,locked=false,task=false){return locked?'共用会话需按顺序执行，固定为 1 条。':(task?'下次继续或重试时生效，最多 50 条。':'同时处理几条案例；1 为逐条，建议先用 3。')+(Number(value)>10?' 较高并行可能触发接口限流。':'');}
function concurrencyField(value,{id='concurrency',locked=false,task=false}={}){return `<div class="field concurrency-field"><label class="field-label" for="${id}">并行数量<span class="field-range">1–50 条</span></label><input id="${id}" name="concurrency" type="number" min="1" max="50" step="1" inputmode="numeric" required aria-required="true" aria-describedby="${id}-hint" value="${locked?1:e(value)}" data-unlocked-value="${e(value)}" ${locked?'disabled':''}><small id="${id}-hint">${concurrencyHint(value,locked,task)}</small></div>`;}
function validateConcurrency(input){if(!input)return;const ok=validConcurrency(input.value);input.setCustomValidity(ok?'':'并行数量请输入 1–50 之间的整数。');input.setAttribute('aria-invalid',String(!ok));return ok;}
function readConcurrency(input){if(!validateConcurrency(input)){input?.reportValidity();throw Error('并行数量请输入 1–50 之间的整数。');}return Number(input.value);}
function syncWizardConcurrency(){const form=$('#wizard-config'),input=form?.elements.concurrency;if(!input)return;const agent=S.boot.agents.find(a=>a.id===form.elements.agentId?.value),locked=sharedSession(form.elements.mode.value,agent);if(locked&&!input.disabled){input.dataset.unlockedValue=input.value;input.value='1';}else if(!locked&&input.disabled)input.value=input.dataset.unlockedValue||'3';input.disabled=locked;validateConcurrency(input);$('#concurrency-hint').textContent=concurrencyHint(input.value,locked);}
function wizardData(form){return {...formData(form),concurrency:Number(form.elements.concurrency.value)};}
function taskRenderKey(task){return JSON.stringify([task.summary,task.status,task.continuedTaskId,task.concurrency,task.rows.map(r=>[r.status,r.error])]);}
function errorSlot(){return '<div class="inline-error" role="alert" tabindex="-1"></div>';}
function formError(form,err){if(err.silent||!form.isConnected)return;const target=form.querySelector('.inline-error');target?.replaceChildren(document.createTextNode(err.message));target?.focus();toast(err.message);}
function formData(form){return Object.fromEntries(new FormData(form));}
function flow(step,taskId){const names=['准备案例','配置评测','运行评测','复核归因','导出报告'],t=taskId&&S.task?.id===taskId?S.task:null,summary=t?.summary,graded=Boolean(summary?.total&&summary.graded===summary.total&&!['running','paused','stopping'].includes(t.status)),completed={1:Boolean(t?.snapshot.dataset.rows.length||S.boot?.datasets.some(d=>d.id===S.draft.datasetId&&d.rowCount>0)),2:Boolean(t),3:graded,4:Boolean(graded&&summary.reviewed>0&&summary.reviewPending===0),5:false};return `<nav class="flow" aria-label="评测步骤">${names.map((label,i)=>{const n=i+1,current=n===step,done=!current&&completed[n],href=n===1?'/wizard/1':n===2?'/wizard/2':taskId?(n===3?`/task/${taskId}`:n===4?`/review/${taskId}`:`/report/${taskId}`):'',clickable=href&&!current&&(n<step||Boolean(taskId));return `<${clickable?'a':'div'} ${clickable?`href="#${href}"`:''} class="flow-item ${current?'current':done?'done':''}" ${current?'aria-current="step"':''}><span class="flow-num" aria-hidden="true">${done?'✓':n}</span><span>${label}${done?'<span class="sr-only">，已完成</span>':''}</span></${clickable?'a':'div'}>`;}).join('')}</nav>`;}
function head(title,sub='',action=''){return `<div class="page-head"><div><h1 id="page-title" tabindex="-1">${e(title)}</h1>${sub?`<p class="home-sub">${e(sub)}</p>`:''}</div>${action}</div>`;}
function stepHead(n,title,sub,id){return `${flow(n,id)}<div class="step-title"><div><h1 id="page-title" tabindex="-1">${e(title)}</h1>${sub?`<p>${e(sub)}</p>`:''}</div></div>`;}
function bar(back,next,notes=''){const label=back==='/tasks'?'返回任务列表':back==='/configs'?'返回配置':/^\/task\//.test(back)?'返回评测结果':back==='/wizard/2'&&['agent','rubric'].includes(route().parts[0])?'返回评测':'上一步';return `<div class="action-bar"><a class="back" href="#${back}">← ${label}</a><div class="tools">${notes}${next}</div></div>`;}
function empty(title,sub,action){return `<div class="panel empty"><h2>${e(title)}</h2><p>${e(sub)}</p>${action}</div>`;}
function parsed(value){if(value&&typeof value==='object')return value;if(typeof value!=='string')return null;try{return JSON.parse(value);}catch{return null;}}
function textValue(value){if(value==null)return '待确认';if(typeof value==='boolean')return value?'是':'否';if(typeof value==='object')return JSON.stringify(value);return String(value);}
const labels={grade:'年级',currentScore:'当前成绩',pain:'需求与困难',goal:'目标',budget:'预算',decisionMaker:'决策人',summary:'总结',understanding:'客户理解',decision:'销售决策',profile:'客户档案',signals:'意向信号',unknowns:'待确认信息',evidence:'原话证据',fieldEvidence:'字段来源',basis:'来源',messageId:'消息ID',quote:'引用原文',stage:'当前阶段',obstacle:'主要障碍',action:'下一步动作',rationale:'建议理由',reminders:'内部提醒',taskProposals:'跟进任务建议',citations:'资料引用',name:'姓名',notes:'内部备注',followupStatus:'跟进状态',profileOverrides:'销售确认信息',value:'内容',reason:'原因',updatedAt:'更新时间',title:'标题',timing:'执行时间',id:'ID',source:'来源',type:'类型',content:'正文',validUntil:'有效期至',enabled:'是否启用',scope:'适用范围',version:'版本',sourceId:'资料ID',sourceTitle:'资料名称'};
const basisLabels={customer_quote:'客户原话',sales_confirmed:'销售已确认',sales_recorded:'销售录入',model_inference:'模型推断',unknown:'未知'};
function readable(value,depth=0){if(value==null)return '<span class="muted">待确认</span>';if(typeof value!=='object')return `<span class="plain-text">${e(basisLabels[value]||textValue(value))}</span>`;if(depth>7)return `<pre class="trace">${e(JSON.stringify(value,null,2))}</pre>`;if(Array.isArray(value))return value.length?`<ul class="readable-list">${value.map(v=>`<li>${readable(v,depth+1)}</li>`).join('')}</ul>`:'<span class="muted">无</span>';return `<dl class="readable-fields">${Object.entries(value).map(([k,v])=>`<div><dt>${e(labels[k]||k)}</dt><dd>${readable(v,depth+1)}</dd></div>`).join('')}</dl>`;}
function block(label,content){return `<div class="original structured"><label>${e(label)}</label>${content}</div>`;}
function fold(label,content,open=false){return `<details class="details" ${open?'open':''}><summary>${e(label)}</summary>${content}</details>`;}
function caseContext(input){const c=parsed(input.context)||{}, raw=parsed(input.case_json)||{}, x=raw.input||{};return {...x,...c,as_of:c.as_of||raw.as_of||input.as_of,previous:c.previous??x.previous};}
function criteriaView(value,compact=false){const c=parsed(value);if(!c||typeof c!=='object')return `<span class="plain-text">${e(value||'未填写判定要求')}</span>`;const groups=[['must_do','应做到'],['must_not','不得'],...(!compact?[['manual_review','人工复核关注']]:[])];const known=groups.filter(([k])=>c[k]);if(!known.length)return readable(c);return known.map(([k,label])=>`<div class="criterion"><strong>${label}</strong>${readable(c[k])}</div>`).join('');}
function contextPreview(input){const c=caseContext(input);if(!Object.keys(c).some(k=>c[k]!=null&&c[k]!==''))return input.context?e(input.context):'无补充资料';if(!parsed(input.context)&&!parsed(input.case_json))return e(input.context||'无补充资料');return `<div class="preview-meta">${e(c.knowledge?.length?`${c.knowledge.length}份知识库资料`:'无知识库资料')}${c.history?.length?` · ${c.history.length}条沟通`:''}${c.instruction?'<br>任务要求：'+e(c.instruction):''}${c.previous?'<br>含改写前结果':''}</div>`;}
function historyView(history){return Array.isArray(history)?history.map(m=>`<div class="message"><span class="message-role">${e({customer:'客户原话',sales:'销售消息',system:'系统',assistant:'Agent回复'}[m.role]||m.role||'消息')} <small>${e(m.id||'')}</small></span><p>${e(m.text??m.content??'')}</p></div>`).join(''):readable(history);}
function inputView(input,referenceColumn='criteria'){const c=caseContext(input), parsedContext=parsed(input.context);return block('用户输入原文',`<div class="plain-text">${e(input.user_input||'未填写')}</div>`)+(c.instruction?block('本次任务要求',`<div class="plain-text">${e(c.instruction)}</div>`):'')+block('本例判定要求',criteriaView(input[referenceColumn]))+fold('沟通记录与客户背景',`${c.history?historyView(c.history):'<p class="muted">无历史消息</p>'}${c.customer?block('客户背景（独立于客户原话）',readable(c.customer)):''}`)+fold(`知识库资料${c.knowledge?.length?' · '+c.knowledge.length+'份':''}`,`<p class="scoped-help">本案例给 Agent 参考的资料</p>`+(c.knowledge?readable(c.knowledge):readable(parsedContext||input.context||'无')))+(c.previous?fold('改写前结果',answerView(c.previous,{compact:true})): '');}
function answerObject(answer){const a=parsed(answer);return a?.output&&typeof a.output==='object'?a.output:a;}
function finalReply(answer){const a=answerObject(answer);if(!a)return String(answer??'');return a.assistance?.suggestedReply??a.suggestedReply??a.reply??a.answer??a.text??null;}
function answerView(answer,{compact=false}={}){const a=answerObject(answer),reply=finalReply(answer);if(!a||typeof a!=='object')return block('Agent 回答原文',`<div class="plain-text">${e(answer||'尚未获得回答')}</div>`);let html=reply!=null?block(a.assistance?'Agent 最终建议话术（原文）':'Agent 回答原文',`<div class="plain-text">${e(typeof reply==='object'?JSON.stringify(reply,null,2):reply)}</div>`):block('Agent 结构化回答',readable(a));if(a.understanding)html+=fold('客户理解',readable(a.understanding));if(a.decision)html+=fold('销售决策',readable(a.decision));if(a.assistance){const {suggestedReply,...internal}=a.assistance;html+=fold('内部提醒与执行建议',readable(internal));}if(a.sources?.length)html+=fold('引用来源',readable(a.sources));if(!compact)html+=fold('查看回答原始 JSON',`<pre class="trace">${e(typeof answer==='string'?answer:JSON.stringify(answer,null,2))}</pre>`);return html;}
function verdict(j){return !j?{label:'尚未评分',kind:'pending'}:j.uncertain?{label:'待确认',kind:'paused'}:j.passed?{label:'通过',kind:'pass'}:{label:'未通过',kind:'error'};}
function verdictBadge(j){const v=verdict(j);return `<span class="status ${v.kind}">${v.label}</span>`;}
function judgmentView(row,rubric){const j=row.judgment;if(!j)return `<div class="banner-info"><strong>自动评分尚未完成</strong><p>${e(row.error||'回答已保存，可以先人工复核。')}</p></div>`;const rules=rubric.dimensionRules||[],dims=j.dimensions||{};const entries=Array.isArray(dims)?dims.map((d,i)=>[d.key||rules[i]?.key||String(i),d]):Object.entries(dims);return `<section class="judgment-card"><div class="judgment-heading"><strong>自动评分 ${j.score} / ${rubric.scoreMax}</strong>${verdictBadge(j)}</div><p class="plain-text">${e(j.reason)}</p>${j.uncertain?'<p class="scoped-help">此条待确认，暂不计入自动通过率分母。</p>':''}${entries.length?`<div class="dimension-scores">${entries.map(([k,d])=>{const rule=rules.find(x=>x.key===k),score=typeof d==='number'?d:d?.score;return `<div class="dimension-score"><div><strong>${e(rule?.label||d?.label||k)}</strong><span>${e(score??'—')}${rule?` / ${rule.max}`:''}</span></div>${d?.reason?`<p class="plain-text">${e(d.reason)}</p>`:'<p class="muted">旧评分未记录此项扣分原因</p>'}${Array.isArray(d?.evidence)&&d.evidence.length?fold('本项证据',readable(d.evidence)):''}</div>`;}).join('')}</div>`:'<p class="scoped-help">本次评分没有逐项分数，可在评分标准中设置结构化维度。</p>'}${j.dimensionValidated===false?'<p class="micro">旧版评分：未校验逐项得分合计。</p>':''}${j.evidence?.length?fold('评分引用证据',readable(j.evidence)):''}${row.deterministicChecks?.length?fold('规则核对结果',readable(row.deterministicChecks)):''}</section>`;}
function rewriteComparison(row){const c=caseContext(row.input);if(!c.previous)return '';const before=answerObject(c.previous),after=answerObject(row.answer);return `<section class="wizard-card"><h2>改写前后对照</h2><div class="decision-layout">${block('改写前话术',`<div class="plain-text">${e(finalReply(c.previous)||'无')}</div>`)}${block('改写后话术',`<div class="plain-text">${e(finalReply(row.answer)||'未提供话术')}</div>`)}</div>${fold('核对客户理解和销售决策是否保留',`<div class="decision-layout"><div><h3>改写前</h3>${readable({understanding:before?.understanding,decision:before?.decision})}</div><div><h3>改写后</h3>${readable({understanding:after?.understanding,decision:after?.decision})}</div></div>`)}</section>`;}
function rowEvidence(row,t){return `<div class="decision-layout evidence-layout"><div>${inputView(row.input,t.snapshot.rubric.referenceColumn)}</div><div>${answerView(row.answer)}${judgmentView(row,t.snapshot.rubric)}</div></div>`;}
function reviewable(row){return row.answer!=null&&String(row.answer).trim()!=='';}
function needsReview(row){return reviewable(row)&&(!row.judgment||row.judgment.uncertain||!row.judgment.passed);}

function dimensionEditor(d={key:'',label:'',max:0,rule:''}){return `<div class="dimension-editor"><div class="dimension-editor-head"><strong>评分维度</strong>${button('移除','remove-dimension')}</div><div class="dimension-fields"><label>维度名称<input data-dimension="label" value="${e(d.label)}" required></label><label>字段标识<input data-dimension="key" value="${e(d.key)}" pattern="[A-Za-z][A-Za-z0-9_]*" required></label><label>满分<input data-dimension="max" type="number" min="0.000001" step="any" value="${e(d.max)}" required></label></div><label class="dimension-rule">评分和扣分规则<textarea data-dimension="rule" required>${e(d.rule)}</textarea></label></div>`;}
function dimensionValues(){return Array.from(document.querySelectorAll('.dimension-editor')).map(el=>Object.fromEntries(Array.from(el.querySelectorAll('[data-dimension]')).map(x=>[x.dataset.dimension,x.dataset.dimension==='max'?Number(x.value):x.value.trim()])));}
function dimensionTotal(){const form=$('#rubric-form'),target=$('#dimension-total');if(!form||!target)return;const rules=dimensionValues(),sum=rules.reduce((s,x)=>s+x.max,0),base=Number(form.elements.scoreMin.value),max=Number(form.elements.scoreMax.value);target.textContent=rules.length?`总分 = 最低分${base} + 维度满分${sum} = ${base+sum}（目标${max}分）`:'当前沿用文字评分；添加维度后将逐项记录评分理由。';target.classList.toggle('bad',Boolean(rules.length&&Math.abs(base+sum-max)>0.0001));}
function trialContinue(t){if(!t.isTrial)return '';if(t.continuedTaskId)return `<div class="banner-info">已创建完整评测任务。${link('查看完整评测',`/task/${t.continuedTaskId}`,true)}</div>`;const remaining=t.snapshot.dataset.rows.length-t.rows.length;if(remaining<1||['running','paused','stopping'].includes(t.status))return '';return `<div class="trial-continue"><div><strong>接着评测剩余${remaining}条</strong><p>已有回答会复用；评分失败项会继续评分。配置或案例变化后需重新检查。</p></div>${button(`继续评测剩余${remaining}条`,'continue-trial',true)}</div>`;}
function breakdownView(s){const issues=s.issueBreakdown||[],causes=s.attributionBreakdown||[],scenarios=s.scenarioBreakdown||[];return `<section class="wizard-card"><h2>问题分布</h2><div class="decision-layout"><div><h3>人工确认的问题类型</h3>${issues.length?issues.map(x=>`<div class="breakdown-row"><span>${e(x.label)}</span><b>${x.count}条</b></div>`).join(''):'<p class="muted">暂无人工确认问题</p>'}</div><div><h3>原因确认情况</h3>${causes.length?causes.map(x=>`<div class="breakdown-row"><span>${x.label==='confirmed'?'已有证据确认':'待核实'}</span><b>${x.count}条</b></div>`).join(''):'<p class="muted">确认 Bad Case 后记录归因</p>'}</div></div>${scenarios.length?`<h3 class="section-heading">各场景表现</h3><div class="table-scroll"><table class="small-table"><thead><tr><th>场景</th><th>案例数</th><th>通过</th><th>未通过</th><th>待确认</th><th>通过率</th><th>人工确认问题</th></tr></thead><tbody>${scenarios.map(x=>`<tr><td>${e(x.label)}</td><td>${x.total}</td><td>${x.passed}</td><td>${x.notPassed}</td><td>${x.uncertain}</td><td>${pct(x.passRate)}<span class="task-meta">已判定${x.decided}条</span></td><td>${x.confirmed}条</td></tr>`).join('')}</tbody></table></div>`:''}</section>`;}
function parseCaseField(form,name,fallback){const str=form.elements[name]?.value.trim();if(!str)return fallback;try{return JSON.parse(str);}catch{throw Error(`${{_history:'沟通记录',_customer:'客户背景',_knowledge:'知识库资料',_previous:'改写前结果'}[name]||name}不是有效JSON，请检查后保存。`);}}
function synchronizeCaseEditor(source){const form=$('#case-form');if(!form?.elements._history)return;try{const history=JSON.parse(form.elements._history.value);if(!Array.isArray(history))return;const last=history.findLast(m=>m.role==='customer');if(!last)return;if(source==='user_input'){last.text=form.elements.user_input.value;form.elements._history.value=JSON.stringify(history,null,2);}else if(source==='_history')form.elements.user_input.value=last.text??last.content??'';}catch{}}
function caseEditData(form,data){const index=data.index,old=index===''?(S.caseEditing||{}):S.dataset.rows[Number(index)],out={...old};for(const[k,v]of Object.entries(data))if(k!=='index'&&!k.startsWith('_'))out[k]=v;if(form.elements._history){const c=caseContext(old),history=parseCaseField(form,'_history',[]),customer=parseCaseField(form,'_customer',{}),knowledge=parseCaseField(form,'_knowledge',[]),previous=parseCaseField(form,'_previous',null);if(!Array.isArray(history)||!Array.isArray(knowledge))throw Error('沟通记录与知识库资料必须是JSON数组。');const last=history.findLast(m=>m.role==='customer');if(last&&last.text!==data.user_input)throw Error('用户输入与最后一条客户消息不一致，请核对沟通记录。');const context={...c,as_of:data._as_of||c.as_of,intent:data._intent||c.intent||'analyze',history,customer,knowledge,instruction:data._instruction||'',previous};out.context=JSON.stringify(context);if(index===''){const {as_of,...input}=context;out.case_json=JSON.stringify({case_id:out.case_id,as_of,input});}}return out;}

function displayTaskName(t){return t.isTrial?String(t.name).replace(/\s*·\s*试跑$/, ''):t.name;}
function taskNext(t){if(['running','stopping'].includes(t.status))return {href:'/task/'+t.id,label:'查看进度'};if(['paused','stopped','interrupted'].includes(t.status))return {href:'/task/'+t.id,label:'继续评测'};if(t.continuedTaskId)return {href:'/task/'+t.continuedTaskId,label:'查看完整评测'};if(t.summary.failed)return {href:'/task/'+t.id,label:'处理失败项'};if(t.isTrial)return {href:'/task/'+t.id,label:'查看试跑'};if(t.summary.reviewPending)return {href:'/review/'+t.id,label:'继续复核'};return {href:'/report/'+t.id,label:'查看报告'};}
function taskOverview(tasks){const stats=[['评测任务',tasks.length,'轮'],['进行中',tasks.filter(t=>['running','paused','stopping'].includes(t.status)).length,'轮'],['待复核任务',tasks.filter(t=>t.summary.reviewPending>0).length,'轮'],['有失败项的任务',tasks.filter(t=>t.summary.failed>0).length,'轮']];return stats.map(([name,value,unit])=>`<div class="overview-card"><span>${name}</span><strong>${value}<small>${unit}</small></strong></div>`).join('');}
function workflowGuide(){return `<ol class="workflow-guide" aria-label="评测流程">${['准备案例','配置评测','运行评分','复核归因','导出报告'].map((text,i)=>`<li class="workflow-step"><span class="workflow-number" aria-hidden="true">${i+1}</span><span>${text}</span></li>`).join('')}</ol>`;}
function taskRows(tasks){const shown=tasks.filter(t=>(S.filter==='review'?t.summary.reviewPending>0:S.filter==='running'?['running','paused','stopping'].includes(t.status):true)&&t.name.toLowerCase().includes(S.search.toLowerCase()));return shown.map(t=>{const next=taskNext(t);return `<tr><td><span class="task-name">${t.isTrial?'<span class="tag">试跑</span> ':''}${e(displayTaskName(t))}</span><span class="task-meta">${e(t.agentName)} · ${date(t.createdAt)}</span></td><td>${status(t.status)}</td><td>${t.summary.graded} / ${t.summary.total}</td><td>${pct(t.summary.passRate)}<span class="task-meta">已判定${t.summary.decided??t.summary.graded}条</span></td><td>${t.summary.confirmed} 条${t.summary.reviewPending?`<span class="task-meta">${t.summary.reviewPending}条待复核</span>`:''}</td><td><a class="report next-action" href="#${next.href}">${next.label} →</a></td></tr>`;}).join('')||'<tr><td colspan="6">没有符合条件的任务。</td></tr>';}
function tasksPage(){const tasks=S.boot.tasks;if(!tasks.length)return head('评测任务')+`<section class="panel welcome-state"><div class="welcome-icon" aria-hidden="true">${icon('chart')}</div><h2>开始第一轮评测</h2><p>选择案例与评分标准，先试跑，再评测整批案例。</p>${link('开始评测','/wizard/1',true)}${workflowGuide()}</section>`;return head('评测任务','',link('＋ 新建评测','/wizard/1',true))+`<div id="task-overview" class="overview-grid">${taskOverview(tasks)}</div>${workflowGuide()}<section class="panel"><div class="panel-head"><h2>全部任务 <span class="list-count">${tasks.length}</span></h2></div><div class="table-controls"><select id="task-filter" aria-label="筛选任务"><option value="all">全部任务</option><option value="review" ${S.filter==='review'?'selected':''}>待复核</option><option value="running" ${S.filter==='running'?'selected':''}>进行中 / 已暂停</option></select><input id="task-search" type="search" placeholder="搜索任务名称" aria-label="搜索任务名称" value="${e(S.search)}"></div><div class="table-scroll"><table><thead><tr><th scope="col">任务 / Agent</th><th scope="col">状态</th><th scope="col">已评分</th><th scope="col">自动通过率</th><th scope="col">人工确认问题</th><th scope="col">下一步</th></tr></thead><tbody id="task-rows">${taskRows(tasks)}</tbody></table></div></section>`;}
function datasetsPage(){const datasets=S.boot.datasets;return head('数据集',`${datasets.length}个数据集`,button('＋ 上传数据集','upload',true))+`<div class="secondary-actions">${button('手动创建','new-dataset')}${link('生成案例','/generate')}<a class="button" href="/api/template" download>下载 CSV 模板</a></div><section class="panel collection-list">${datasets.length?datasets.map(d=>`<article class="collection-item"><div class="collection-icon" aria-hidden="true">${icon('data')}</div><div class="collection-copy"><h2><a href="#/dataset/${d.id}">${e(d.name)}</a></h2><p>${d.rowCount}条案例 · 版本${d.version} · 更新于${date(d.updatedAt)}</p></div><div class="collection-actions">${link('查看与编辑',`/dataset/${d.id}`)}${button('用于评测','use-dataset',false,`data-id="${d.id}" aria-label="使用${e(d.name)}评测"`)}</div></article>`).join(''):'<div class="empty"><h2>还没有数据集</h2><p>上传 CSV / Excel，或手动创建案例。</p></div>'}</section>`;}
async function datasetPage(id){const d=await api('/datasets/'+id);S.dataset=d;return head(d.name,`${d.rows.length}条案例 · 版本${d.version}`,button('用于评测','use-dataset',true,`data-id="${id}"`))+`<div class="secondary-actions">${button('＋ 添加案例','add-case')}${button('匹配字段','map-columns')}${button('重命名','rename-dataset')}${button('复制数据集','copy-dataset')}<a class="button" href="/api/datasets/${id}/export" download>下载CSV</a>${button('删除','delete-dataset',false,`data-id="${id}"`)}</div><section class="panel"><div class="panel-head"><h2>案例列表</h2><span class="muted">输入与发送内容同步保存</span></div><div class="table-scroll"><table class="small-table"><thead><tr><th>ID</th><th>用户输入</th><th>资料</th><th>判定要求</th><th>已有回答</th><th>操作</th></tr></thead><tbody>${d.rows.map((r,i)=>`<tr><td>${e(r.case_id)}</td><td>${e(r.user_input?.slice(0,200)||'未匹配')}</td><td>${contextPreview(r)}</td><td>${criteriaView(r.criteria,true)}</td><td>${r.actual_output?'已填写':'—'}</td><td><button type="button" class="case-link" data-action="edit-case" data-index="${i}">编辑</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function wizard1(){const list=S.boot.datasets,chosen=list.find(d=>d.id===S.draft.datasetId)||list[0];if(chosen)draft({datasetId:chosen.id});return stepHead(1,'选择评测案例','')+`<form id="wizard-data"><section class="wizard-card">${select('datasetId','本轮数据集',list.map(d=>[d.id,`${d.name} · ${d.rowCount}条`]),chosen?.id)}<div class="secondary-actions">${button('上传 CSV / Excel','upload')}${link('生成案例','/generate')}<a class="button" href="/api/template${S.draft.agentId?'?agentId='+encodeURIComponent(S.draft.agentId):''}" download>下载匹配模板</a></div>${chosen?`<div id="dataset-preview"></div><a id="edit-dataset-link" class="config-entry" href="#/dataset/${chosen.id}">编辑案例 / 匹配字段 →</a>`:'<p class="scoped-help">每条案例至少需要用户输入和判定要求。</p>'}${errorSlot()}</section>${bar('/tasks','<button class="button primary" type="submit">下一步：配置评测 →</button>')}</form>`;}
async function fillDatasetPreview(id){const d=await api('/datasets/'+id);if(S.draft.datasetId!==id)return;const holder=$('#dataset-preview');if(!holder)return;holder.innerHTML=`<div class="micro">共${d.rows.length}条，预览前3条。</div><div class="table-scroll"><table class="small-table"><thead><tr><th>用户输入</th><th>资料</th><th>应该做到什么</th></tr></thead><tbody>${d.rows.slice(0,3).map(r=>`<tr><td>${e(r.user_input||'未匹配输入字段')}</td><td>${contextPreview(r)}</td><td>${criteriaView(r.criteria,true)}</td></tr>`).join('')}</tbody></table></div>`;}
function wizard2(){const d=S.boot.datasets.find(x=>x.id===S.draft.datasetId);if(!d){go('/wizard/1');return '';}const agents=S.boot.agents,rubrics=S.boot.rubrics.filter(r=>r.enabled),a=agents.find(x=>x.id===S.draft.agentId)||agents[0],r=rubrics.find(x=>x.id===S.draft.rubricId)||rubrics[0];draft({agentId:a?.id||'',rubricId:r?.id||'',mode:S.draft.mode||'agent',answerColumn:S.draft.answerColumn||'actual_output',concurrency:validConcurrency(S.draft.concurrency)?Number(S.draft.concurrency):3});S.preflight=null;return stepHead(2,'配置本轮评测','')+`<form id="wizard-config"><div class="wizard-config-layout"><section class="wizard-card config-card"><div class="config-card-header"><h2>评测对象</h2><a id="edit-agent-link" class="config-entry" href="#/agent/${a?.id||'new'}?return=wizard" ${S.draft.mode==='existing'?'hidden':''}>${a?'配置连接':'新建连接'} →</a></div>${select('mode','评测方式',[['agent','调用 Agent 后评测'],['existing','只评测已有回答']],S.draft.mode)}<div id="agent-choice" ${S.draft.mode==='existing'?'hidden':''}>${select('agentId','Agent 连接',agents.length?agents.map(a=>[a.id,a.name]):[['','请选择或新建连接']],a?.id)}</div><div id="existing-choice" ${S.draft.mode!=='existing'?'hidden':''}>${field('answerColumn','已有回答所在列',S.draft.answerColumn)}</div></section><section class="wizard-card config-card"><div class="config-card-header"><h2>评分配置</h2><a id="edit-rubric-link" class="config-entry" href="#/rubric/${r?.id||'new'}?return=wizard">${r?'修改配置':'新建标准'} →</a></div>${select('rubricId','本轮评分标准',rubrics.length?rubrics.map(r=>[r.id,r.name]):[['','请选择或新建评分标准']],r?.id)}<div id="rubric-preview">${rubricPreview(r)}</div></section></div><section class="wizard-card run-setup"><h2 class="sr-only">确认并开始评测</h2><div class="run-setup-row"><div class="selection-summary"><div><span class="summary-label">本轮案例</span><strong>${e(d.name)}</strong><span>${d.rowCount}条 · 版本${d.version}</span></div><a class="config-entry" href="#/wizard/1">更换</a></div>${field('name','任务名称',S.draft.name||`${d.name} · 评测`)}</div><div class="run-options">${concurrencyField(S.draft.concurrency,{locked:sharedSession(S.draft.mode,a)})}</div><div id="preflight-result" aria-live="polite"><p class="check-pending">正在检查案例与配置…</p></div>${errorSlot()}</section>${bar('/wizard/1',button('先试跑第1条','preview',true,'disabled')+'<button id="start-run" class="button" type="submit" disabled>运行全部案例</button>')}</form>`;}
function rubricPreview(r){if(!r)return '<p class="scoped-help">选择评分标准后查看规则。</p>';const rules=r.dimensionRules||[];return `<div class="rubric-summary">${rules.length?`<div class="rubric-chips">${rules.map(d=>`<span class="rubric-chip"><span>${e(d.label)}</span><b>${d.max}分</b></span>`).join('')}</div>`:`<details class="details rubric-legacy"><summary>文字评分规则</summary><p class="plain-text">${e(r.dimensions)}</p></details>`}<div class="rubric-threshold"><span>通过门槛</span><strong>${r.passThreshold}分</strong><span>满分${r.scoreMax}${Number(r.scoreMin)!==0?` · 最低${r.scoreMin}分`:''}</span></div>${r.veto?`<details class="rubric-veto"><summary>否决条件</summary><p class="plain-text">${e(r.veto)}</p></details>`:''}</div>`;}
function preflightView(check,data){return `<details class="preflight-details ${check.ready?'is-ready':'has-errors'}" ${check.ready?'':'open'}><summary><span class="check-dot ${check.ready?'ok':'warn'}" aria-hidden="true">${check.ready?'✓':'!'}</span><strong>${check.ready?'配置检查通过':`还有${check.errors?.length||1}项需要处理`}</strong><span class="preflight-caption">${check.ready?`实际连接待试跑验证${check.warnings?.length?` · ${check.warnings.length}项提醒`:''}`:'修正后即可开始'}</span></summary><div class="preflight-body">${check.checks?.length?`<div class="check-list">${check.checks.map(c=>`<div><span class="check-dot ${['pass','ok','ready','success'].includes(c.status)?'ok':'warn'}" aria-hidden="true">${['pass','ok','ready','success'].includes(c.status)?'✓':'!'}</span><span>${e(c.label)}${c.message?`<small>${e(c.message)}</small>`:''}</span></div>`).join('')}</div>`:''}${check.errors?.length?`<ul class="check-errors">${check.errors.map(x=>`<li>${x.caseId?`<strong>${e(x.caseId)}</strong> · `:''}${e(x.message)}</li>`).join('')}</ul>`:''}${check.warnings?.length?`<div class="notice">${check.warnings.map(x=>e(typeof x==='string'?x:x.message)).join('<br>')}</div>`:''}<div class="secondary-actions">${button('重新检查','check-config')}${!check.ready?`${link('修改案例',`/dataset/${data.datasetId}`)}${data.mode==='agent'?link('配置Agent',`/agent/${data.agentId||'new'}?return=wizard`):''}${link('配置评分标准',`/rubric/${data.rubricId||'new'}?return=wizard`)}`:''}</div></div></details>`;}
async function wizardReady(){const form=$('#wizard-config');if(!form)return;syncWizardConcurrency();const data={...wizardData(form),datasetId:S.draft.datasetId};delete data.name;const key=JSON.stringify(data);S.preflightKey=key;S.preflight=null;const buttons=()=>[form.querySelector('#start-run'),form.querySelector('[data-action="preview"]')].filter(Boolean);buttons().forEach(b=>b.disabled=true);const target=$('#preflight-result');target.innerHTML='<p class="check-pending">正在检查案例与配置…</p>';const missing=[];if(!validateConcurrency(form.elements.concurrency))missing.push({field:'并行数量',message:'并行数量请输入 1–50 之间的整数。'});if(data.mode==='agent'&&!data.agentId)missing.push({field:'Agent',message:'请先创建并选择Agent连接。'});if(!data.rubricId)missing.push({field:'评分标准',message:'请先创建并选择评分标准。'});if(missing.length){S.preflight={ready:false,errors:missing,warnings:[],checks:[]};target.innerHTML=preflightView(S.preflight,data);return;}try{const check=await post('/preflight',data);if(S.preflightKey!==key||!form.isConnected)return;S.preflight=check;target.innerHTML=preflightView(check,data);buttons().forEach(b=>b.disabled=!check.ready);}catch(err){if(S.preflightKey===key&&form.isConnected)target.innerHTML=`<div class="error-note">${e(err.message)} ${button('重新检查','check-config')}</div>`;}}
function configsPage(){return head('Agent 与评分标准')+`<section class="panel config-collection"><div class="panel-head"><h2>Agent 连接 <span class="list-count">${S.boot.agents.length}</span></h2>${link('＋ 新建连接','/agent/new',true)}</div><div class="collection-list">${S.boot.agents.length?S.boot.agents.map(a=>`<article class="collection-item"><div class="collection-icon" aria-hidden="true">${icon('layers')}</div><div class="collection-copy"><h3>${e(a.name)}</h3><p>${e(a.url)}</p><p>版本${a.version}${a.adapterType==='sales'?' · 提示词由 Agent 服务管理':''}</p></div><div class="collection-actions">${link('编辑',`/agent/${a.id}`)}${button('删除','delete-config',false,`data-id="${a.id}" data-kind="agents" aria-label="删除${e(a.name)}"`)}</div></article>`).join(''):'<p class="collection-empty">尚未配置连接。也可在评测时选择已有回答。</p>'}</div><div class="collection-footer">${button('导入销售示例数据','sales-preset')}</div></section><section class="panel config-collection"><div class="panel-head"><h2>评分标准 <span class="list-count">${S.boot.rubrics.length}</span></h2>${link('＋ 新建标准','/rubric/new',true)}</div><div class="collection-list">${S.boot.rubrics.map(r=>`<article class="collection-item"><div class="collection-icon" aria-hidden="true">${icon('sliders')}</div><div class="collection-copy"><h3>${e(r.name)} ${!r.enabled?'<span class="tag">停用</span>':''}</h3><p>${r.baseUrl&&r.model?`模型：${e(r.model)}`:'待配置评判模型'} · 版本${r.version}</p><p>通过门槛 ${r.passThreshold}分${r.dimensionRules?.length?` · ${r.dimensionRules.length}个评分维度`:''}</p></div><div class="collection-actions">${link('编辑',`/rubric/${r.id}`)}${button('删除','delete-config',false,`data-id="${r.id}" data-kind="rubrics" aria-label="删除${e(r.name)}"`)}</div></article>`).join('')}</div></section>`;}
function agentForm(id,back){const c={...S.boot.defaults.agent,...S.boot.agents.find(a=>a.id===id)},sales=c.adapterType==='sales';return head(id==='new'?'接入Agent':'配置Agent')+`<form id="agent-form" data-guard><input name="id" type="hidden" value="${id==='new'?'':e(id)}"><input name="back" type="hidden" value="${e(back)}"><input name="adapterType" type="hidden" value="${e(c.adapterType||'generic')}"><section class="wizard-card"><h2>基本连接</h2>${field('name','Agent名称',c.name,'text','',true)}${field('url','API地址',c.url,'url','填写待评测Agent提供的接口。',true)}${field('apiKey','API Key / Token','','password',c.hasApiKey?'已保存密钥；留空保留原值。':'没有鉴权的接口可留空。')}${c.hasApiKey?field('clearApiKey','清除已保存密钥',false,'checkbox'):''}<details class="details"><summary>从 cURL 导入</summary>${field('curl','粘贴cURL调用示例','','textarea')}${button('识别并填入','import-curl')}</details></section><section class="wizard-card"><h2>Agent提示词</h2>${sales?'<div class="notice">该 Agent 的提示词由 Agent 服务管理，本页不能修改。评测会使用服务当前的提示词。</div>':`${field('systemPrompt','系统提示词',c.systemPrompt,'textarea')}${field('userPrompt','用户提示词模板',c.userPrompt,'textarea')}<p class="micro">将提示词变量绑定到下方请求体后，才会传入接口。</p>`}</section><section class="wizard-card"><details><summary>高级配置 · 请求格式与字段映射</summary>${select('method','请求方式',['POST','GET','PUT','PATCH'],c.method)}${field('headers','请求Header（JSON）',c.headers,'textarea','通过{{api_key}}引用密钥。',true)}${field('inputBindings','输入字段绑定（JSON）',c.inputBindings,'textarea','左侧为请求变量，右侧为数据集列名。',true)}${field('requestTemplate','请求体模板（JSON）',c.requestTemplate,'textarea','可引用{{system_prompt}}、{{user_prompt}}和{{session_id}}。',true)}${field('outputPath','最终回答提取路径',c.outputPath,'text','例如$.answer或$.choices[0].message.content。',true)}${field('extractRules','其他输出提取规则（JSON）',c.extractRules,'textarea','例如{"tool_calls":{"path":"$.tool_calls"}}。')}</details></section><section class="wizard-card"><details><summary>高级配置 · 流式、会话与运行限制</summary><div class="decision-layout">${select('protocol','响应格式',[['auto','自动识别'],['json','JSON'],['sse','SSE'],['ndjson','NDJSON'],['text','纯文本']],c.protocol)}${select('sessionMode','会话策略',[['per_case','每条案例独立会话'],['dataset','沿用数据集会话ID']],c.sessionMode)}${field('sessionColumn','会话ID所在列',c.sessionColumn)}${field('timeoutMs','请求超时（毫秒）',c.timeoutMs,'number')}${field('idleTimeoutMs','响应空闲超时（毫秒）',c.idleTimeoutMs,'number')}${field('retries','失败重试次数',c.retries,'number')}<input type="hidden" name="concurrency" value="${e(c.concurrency)}">${field('doneSignal','流式结束信号',c.doneSignal)}${field('doneRequired','必须收到结束信号',c.doneRequired,'checkbox')}</div></details></section>${errorSlot()}${bar(back,'<button class="button primary" type="submit">保存配置并返回 →</button>')}</form>`;}
function rubricForm(id,back){const existing=S.boot.rubrics.find(r=>r.id===id),c={...S.boot.defaults.rubric,...existing},rules=id==='new'?(c.dimensionRules||[]):(existing?.dimensionRules||[]);return head('配置评分标准与评判模型')+`<form id="rubric-form" data-guard><input name="id" type="hidden" value="${id==='new'?'':e(id)}"><input name="back" type="hidden" value="${e(back)}"><section class="wizard-card"><h2>评判模型连接</h2>${field('baseUrl','Base URL',c.baseUrl,'url','兼容OpenAI接口，如https://服务地址/v1。')}${field('model','模型名称',c.model,'text','填写服务商提供的模型ID。')}${field('apiKey','API Key','','password',c.hasApiKey?'已保存；留空保留。':'仅在本机后端使用。')}${c.hasApiKey?field('clearApiKey','清除密钥',false,'checkbox'):''}<details class="details"><summary>模型高级选项</summary>${field('timeoutMs','单次评分超时（毫秒）',c.timeoutMs,'number')}${field('thinkingEnabled','思考模式（服务须支持enable_thinking）',c.thinkingEnabled,'checkbox')}</details></section><section class="wizard-card"><h2>评分标准</h2>${field('name','标准名称',c.name,'text','',true)}<div class="decision-layout">${field('scoreMin','最低分',c.scoreMin,'number')}${field('scoreMax','最高分',c.scoreMax,'number')}${field('passThreshold','通过分数',c.passThreshold,'number')}${field('enabled','启用此评分标准',c.enabled,'checkbox')}</div><div class="config-title"><h2>逐项评分维度</h2>${button('＋ 添加维度','add-dimension')}</div><p class="scoped-help">每一项都保存得分、理由和证据；总分由最低分加各项得分计算。</p><div id="dimension-rules">${rules.map(d=>dimensionEditor(d)).join('')}</div><div id="dimension-total" class="micro"></div><details class="details" ${!rules.length?'open':''}><summary>补充说明 / 旧版文字规则</summary>${field('dimensions','评分说明',c.dimensions,'textarea','未设置逐项维度时，继续使用文字规则。')}</details>${field('veto','必须判失败的条件',c.veto,'textarea')}</section><section class="wizard-card"><details><summary>高级配置 · 判定列与评判提示词</summary>${field('referenceColumn','案例判定要求所在列',c.referenceColumn,'text','默认criteria；支持自定义列名。',true)}${field('systemPrompt','裁判系统提示词',c.systemPrompt,'textarea','负责评分的模型使用此提示词。',true)}${field('userPrompt','裁判用户提示词模板',c.userPrompt,'textarea','支持{{input.xxx}}、{{outputs.xxx}}、{{reference_output}}、{{outputs_json}}、{{result.status}}、{{rubric}}、{{veto_rules}}、{{pass_threshold}}。',true)}</details></section>${errorSlot()}${bar(back,'<button class="button primary" type="submit">保存标准并返回 →</button>')}</form>`;}
function generatePage(){return head('生成评测集','生成的是合成案例，是否成为Bad Case取决于Agent实际回答。')+`<form id="generate-form"><section class="wizard-card">${field('name','数据集名称','新生成评测集')}${select('agentId','这批案例用于哪个Agent',[['','通用Agent / 已有回答'],...S.boot.agents.map(a=>[a.id,a.name])],S.draft.agentId||'',false)}${field('scene','描述业务场景','','textarea','说明Agent做什么、允许哪些动作、有哪些业务限制。',true)}<div class="decision-layout">${field('count','案例数量（1–100）',50,'number')}${select('rubricId','用于生成的模型配置',S.boot.rubrics.map(r=>[r.id,`${r.name}${r.baseUrl&&r.model?'':'（模型未配置）'}`]),S.draft.rubricId)}</div><a class="config-entry" href="#/configs">先配置模型 →</a>${errorSlot()}<button type="submit" class="button primary">生成案例草稿</button></section></form><div id="generated-preview"></div>`;}
function generatedHtml(){const rows=S.generated?.rows||[];return `<section class="wizard-card"><div class="config-title"><h2>${rows.length}条案例草稿</h2>${button('检查后保存为数据集','save-generated',true)}</div><p class="scoped-help">保存后可逐条编辑输入、资料和判定要求。</p><div class="table-scroll"><table class="small-table"><thead><tr><th>ID</th><th>用户输入</th><th>资料</th><th>判定要求</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(r.case_id)}</td><td>${e(r.user_input)}</td><td>${contextPreview(r)}</td><td>${criteriaView(r.criteria,true)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function caseRows(task,filter='all'){return task.rows.filter(r=>filter==='issues'?needsReview(r):filter==='errors'?r.status==='error':filter==='confirmed'?r.review?.decision==='bad':filter==='uncertain'?r.judgment?.uncertain:true).map(r=>`<tr><td>${e(r.input.case_id)}</td><td>${e((r.input.user_input||'').slice(0,100))}</td><td>${status(r.status)}</td><td>${r.judgment?.score??'—'}</td><td>${r.judgment?verdictBadge(r.judgment):r.error?e(r.error.slice(0,100)):'—'}</td><td>${{bad:'确认问题',normal:'正常',disputed:'争议'}[r.review?.decision]||'未复核'}</td><td>${reviewable(r)?`<a class="report" href="#/review/${task.id}?row=${r.id}&scope=all">查看与复核</a>`:button('详情','row-detail',false,`data-row="${r.id}"`)}</td></tr>`).join('')||'<tr><td colspan="7">没有符合条件的案例。</td></tr>';}
function resultsTable(t){return `<section class="panel"><div class="panel-head"><h2>逐条结果</h2><span class="micro">总览指标按全部案例计算</span></div><div class="table-controls"><select id="case-filter" aria-label="筛选案例"><option value="all">全部案例</option><option value="issues">未通过 / 待确认 / 评分未完成</option><option value="uncertain">仅待确认</option><option value="errors">调用或评分失败</option><option value="confirmed">人工确认问题</option></select></div><div class="table-scroll"><table class="small-table"><thead><tr><th>ID</th><th>用户输入</th><th>执行状态</th><th>分数</th><th>自动判定 / 错误</th><th>人工复核</th><th>操作</th></tr></thead><tbody id="case-rows">${caseRows(t)}</tbody></table></div></section>`;}
function taskPage(t){const s=t.summary,active=['running','paused','stopping'].includes(t.status),running=t.rows.filter(r=>['calling','judging'].includes(r.status)).length,canChange=['paused','stopped','interrupted','completed_with_errors'].includes(t.status);return stepHead(3,t.isTrial?'试跑第1条':'运行与逐条评分','结果自动保存，可随时从任务列表回来查看。',t.id)+`<section class="wizard-card"><div class="config-title"><h2>${e(displayTaskName(t))} ${t.isTrial?'<span class="tag">试跑</span>':''}</h2>${status(t.status)}</div><div class="summarybar" aria-live="polite" aria-atomic="true"><span>有效回答 <b>${s.answered}/${s.total}</b></span><span>完成评分 <b>${s.graded}/${s.total}</b></span><span>错误 <b>${s.failed}</b></span></div><div class="progress" role="progressbar" aria-label="案例处理进度" aria-valuenow="${Math.min(100,Math.round(100*(s.graded+s.failed)/(s.total||1)))}" aria-valuemin="0" aria-valuemax="100"><div style="width:${Math.min(100,100*(s.graded+s.failed)/(s.total||1))}%"></div></div><div class="parallel-state" aria-live="polite"><span>并行设置 <strong>${taskConcurrency(t)} 条</strong></span><span>正在处理 <strong>${running} 条</strong></span></div>${canChange?`<div class="task-run-options">${concurrencyField(taskConcurrency(t),{id:'task-concurrency',locked:sharedSession(t.mode,t.snapshot.agent),task:true})}</div>`:''}<div class="secondary-actions">${t.status==='running'?button('暂停','control',false,'data-control="pause"'):''}${['paused','stopped','interrupted'].includes(t.status)?button('继续运行','control',false,`data-control="resume" ${running>0?'disabled':''}`):''}${['running','paused'].includes(t.status)?button('停止','control',false,'data-control="stop"'):''}${s.failed&&!active?button('重试失败项','control',false,`data-control="retry" ${running>0?'disabled':''}`):''}${!active&&!t.isTrial?button('用新标准重新评分','rescore'):''}</div>${t.status==='paused'&&running>0?`<p class="micro" role="status">等待当前 ${running} 条完成后可继续。</p>`:''}${t.status==='stopping'?'<div class="notice">正在停止本次调用，停止完成后可继续。已获得的回答会保留。</div>':''}${t.status==='interrupted'?'<div class="error-note">服务曾中断，可点击“继续运行”；已有有效回答会被复用。</div>':''}${t.reusedCases?`<p class="micro">已复用${t.reusedCases}条回答。</p>`:''}${trialContinue(t)}</section>${t.isTrial&&t.rows[0]&&reviewable(t.rows[0])?`<section class="wizard-card"><h2>试跑结果 · ${e(t.rows[0].input.case_id)}</h2>${rowEvidence(t.rows[0],t)}</section>${rewriteComparison(t.rows[0])}`:''}${resultsTable(t)}${bar('/wizard/2',active&&!s.reviewPending?`<button type="button" class="button primary" disabled>${t.status==='paused'?'已暂停':t.status==='stopping'?'正在停止…':'正在评测…'}</button>`:link(s.reviewPending?`复核${active?'已有的':''}${s.reviewPending}条${active?'回答':'待确认结果'} →`:'查看报告 →',s.reviewPending?`/review/${t.id}`:`/report/${t.id}`,true))}`;}
function reviewPage(t,q){const scope=q.get('scope')||'issues',suspects=t.rows.filter(r=>reviewable(r)&&(scope==='all'||needsReview(r)));let row=q.get('row')?t.rows.find(r=>r.id===q.get('row')):suspects.find(r=>!r.review?.decision);if(!row||!reviewable(row))return stepHead(4,'复核与归因','可继续抽查自动通过的回答。',t.id)+empty('当前没有待复核的结果','已获得回答的案例都可以人工复核。',link('抽查全部案例',`/review/${t.id}?scope=all`,true)+link('查看报告',`/report/${t.id}`));S.reviewRow=row;const i=Math.max(0,suspects.findIndex(r=>r.id===row.id));return stepHead(4,'核对原文，确认问题','先确认回答的问题，再标注原因是否已经核实。',t.id)+`<section class="wizard-card"><div class="case-head"><h2>${e(row.input.case_id)} · ${e(row.input.scenario||row.input.category||'案例')}</h2><div class="case-pager"><span>${i+1}/${suspects.length||t.rows.length}</span>${i>0?link('上一条',`/review/${t.id}?row=${suspects[i-1].id}&scope=${scope}`):''}${i<suspects.length-1?link('下一条',`/review/${t.id}?row=${suspects[i+1].id}&scope=${scope}`):''}</div></div>${rowEvidence(row,t)}<details class="case-trace"><summary>完整输入、调用过程与评分提示词</summary><pre class="trace">${e(JSON.stringify({input:row.input,request:row.request,outputs:row.outputs,agentPrompt:row.agentPrompt,judgePrompt:row.judgePrompt,judgeRaw:row.judgeRaw,usage:row.usage},null,2))}</pre></details></section>${rewriteComparison(row)}<form id="review-form"><input type="hidden" name="rowId" value="${row.id}"><input type="hidden" name="scope" value="${scope}"><section class="wizard-card"><h2>你确认这是问题吗？</h2><div class="review-options">${[['bad','确认Bad Case'],['normal','判定正常'],['disputed','有争议']].map(([v,l])=>`<label class="option"><input type="radio" name="decision" value="${v}" ${row.review?.decision===v?'checked':''} required>${l}</label>`).join('')}</div><div id="attribution-fields" ${row.review?.decision==='normal'?'hidden':''}>${select('issueType','问题类型',[['','请选择'],['事实编造','事实编造'],['资料适用错误','资料适用错误'],['动作不合理','动作不合理'],['联系边界','联系边界'],['话术不可用','话术不可用'],['多轮状态错误','多轮状态错误'],['评判误判','评判误判'],['其他','其他']],row.review?.issueType||'',false)}${select('attributionStatus','原因是否已核实',[['pending','待核实'],['confirmed','已有证据确认']],row.review?.attributionStatus||'pending')}${field('attribution','归因与证据',row.review?.attribution||'','textarea','写明观察到的问题与依据；具体原因还不清楚时，保留“待核实”。')}</div>${field('note','复核备注',row.review?.note||'','textarea')}${errorSlot()}</section>${bar(`/task/${t.id}`,'<button class="button primary" type="submit">保存复核，继续 →</button>',link('暂不复核，查看报告',`/report/${t.id}`))}</form>`;}
function reportPage(t){const s=t.summary,confirmed=t.rows.filter(r=>['bad','disputed'].includes(r.review?.decision)),decided=s.decided??(s.graded-s.uncertain);return stepHead(5,'评测报告',t.name,t.id)+`<div class="result-grid"><div class="result-box">评分覆盖率<b>${pct(s.graded/s.total)}</b><small>${s.graded}/${s.total}条已评分</small></div><div class="result-box">自动通过率<b>${pct(s.passRate)}</b><small>${s.passed}/${decided}条已明确判定</small></div><div class="result-box alert">人工确认问题<b>${s.confirmed}条</b><small>已复核${s.reviewed}条</small></div></div>${s.failed?`<div class="error-note">${s.failed}条调用或评分失败。${link('处理失败项',`/task/${t.id}`)}</div>`:''}${s.pending?`<div class="banner-info">${s.pending}条尚未完成，当前报告为阶段结果。</div>`:''}<section class="wizard-card"><h2>本轮结论</h2><div class="verdict-counts"><span>通过 <b>${s.passed}</b></span><span>未通过 <b>${s.notPassed??s.graded-s.passed-s.uncertain}</b></span><span>待确认 <b>${s.uncertain}</b></span></div><p class="report-summary">人工复核 ${s.reviewed} 条，确认问题 ${s.confirmed} 条，争议 ${s.disputed} 条；待复核 ${s.reviewPending} 条。</p><details class="details"><summary>计算公式与评测范围</summary><p>自动通过率 = 通过数 ÷（通过数 + 未通过数）= ${s.passed} ÷ ${decided} = ${pct(s.passRate)}。</p><p>评分覆盖率 = 已完成评分数 ÷ 本轮案例总数 = ${s.graded} ÷ ${s.total} = ${pct(s.graded/s.total)}。</p><p>人工确认问题比例（仅已复核案例）= ${s.confirmed} ÷ ${s.reviewed} = ${s.reviewed?pct(s.confirmed/s.reviewed):'—'}。</p><p class="micro">待确认、评分失败和未完成案例均不计入自动通过率分母。上述结果只代表本批案例，不代表线上成交转化率。</p><p>${e(t.snapshot.dataset.name)} · 版本${t.snapshot.dataset.version} · 本轮${s.total}条；${e(t.snapshot.agent?.name||'已有回答')}。</p>${rubricPreview(t.snapshot.rubric)}</details><div class="secondary-actions">${link('继续复核 / 抽查',`/review/${t.id}?scope=all`)}${button('用新标准重新评分','rescore')}</div>${trialContinue(t)}</section>${breakdownView(s)}<section class="wizard-card"><h2>Bad Case 与归因</h2>${confirmed.length?confirmed.map(r=>`<details class="details"><summary>${e(r.input.case_id)} · ${e(r.review.issueType||'未分类')} · ${r.review.decision==='bad'?'确认问题':'争议'} · ${r.review.attributionStatus==='confirmed'?'原因已确认':'原因待核实'}</summary>${block('用户原文',`<div class="plain-text">${e(r.input.user_input||'')}</div>`)}${answerView(r.answer)}${block('归因与证据',`<div class="plain-text">${e(r.review.attribution||'待核实')}</div>`)}<a class="config-entry" href="#/review/${t.id}?row=${r.id}&scope=all">查看全部证据与修改复核 →</a></details>`).join(''):'<p class="scoped-help">尚无人工确认的问题，请先复核自动未通过和待确认案例。</p>'}</section>${resultsTable(t)}<section class="wizard-card"><h2>导出结果</h2><div class="download-links">${['md','xlsx','csv','json'].map(f=>`<a class="button" href="/api/tasks/${t.id}/export?format=${f}" download>${{md:'完整报告 Markdown',xlsx:'结果 Excel',csv:'结果 CSV',json:'执行与配置记录 JSON'}[f]}</a>`).join('')}</div></section>${bar('/tasks',`<a class="button primary" href="/api/tasks/${t.id}/export?format=md" download>导出完整报告</a>`)}`;}
async function render(){if(!workspaceReady()){renderAuthScreen();return;}const authEpoch=S.authEpoch;showWorkspace();const renderHash=location.hash;const {parts:p,query:q}=route();try{await refresh();const section=p[0]||'tasks';const config=['configs','agent','rubric'].includes(section);app.className='content'+(['wizard','agent','rubric','task','review','report'].includes(section)?' guide':'');document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(config?'configs':['datasets','dataset','generate'].includes(section)?'datasets':'tasks');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#crumb').textContent=config?'Agent 与评分标准':['dataset','datasets','generate'].includes(section)?'数据集':'评测任务';S.task=null;
 let html;if(section==='tasks')html=tasksPage();else if(section==='datasets')html=datasetsPage();else if(section==='dataset')html=await datasetPage(p[1]);else if(section==='wizard')html=Number(p[1])===2?wizard2():wizard1();else if(section==='configs')html=configsPage();else if(section==='agent')html=agentForm(p[1],q.get('return')==='wizard'?'/wizard/2':'/configs');else if(section==='rubric')html=rubricForm(p[1],q.get('return')==='wizard'?'/wizard/2':'/configs');else if(section==='generate')html=generatePage();else if(['task','review','report'].includes(section)){S.task=await api('/tasks/'+p[1]);html=section==='task'?taskPage(S.task):section==='review'?reviewPage(S.task,q):reportPage(S.task);}else html=tasksPage();if(location.hash!==renderHash||authEpoch!==S.authEpoch||!workspaceReady())return;app.innerHTML=html;S.dirty=false;window.scrollTo(0,0);const title=app.querySelector('h1');document.title=(title?.textContent||'评测工作台')+' · Eval Studio';if(S.renderedHash!==renderHash)title?.focus({preventScroll:true});S.renderedHash=renderHash;if(section==='rubric')dimensionTotal();if(section==='wizard'&&Number(p[1])===2){if($('#agentId')){$('#agentId').required=S.draft.mode!=='existing';$('#agentId').disabled=S.draft.mode==='existing';}await wizardReady();}if(section==='wizard'&&Number(p[1])!==2&&S.draft.datasetId)await fillDatasetPreview(S.draft.datasetId);
 }catch(err){if(location.hash!==renderHash||authEpoch!==S.authEpoch||!workspaceReady()||err.silent)return;app.innerHTML=empty('暂时无法打开',err.message,link('返回任务列表','/tasks'));document.title='暂时无法打开 · Eval Studio';app.focus();}}
function openModal(title,html){modal.innerHTML=`<div class="dialog-head"><h2>${e(title)}</h2><button class="close-btn" type="button" data-action="close-modal" aria-label="关闭">×</button></div>${html}`;modal.showModal();}
function newSalesCase(){const example=S.dataset.rows.find(r=>r.case_json),c=caseContext(example||{});let n=S.dataset.rows.length+1,id='C'+String(n).padStart(3,'0');while(S.dataset.rows.some(r=>r.case_id===id))id='C'+String(++n).padStart(3,'0');const input={intent:'analyze',instruction:'',customer:{name:'合成客户',notes:'',followupStatus:'跟进中'},history:[{id:id+'-m1',role:'customer',text:''}],knowledge:[],previous:null},as_of=c.as_of||new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});return {case_id:id,user_input:'',criteria:'',actual_output:'',context:JSON.stringify({as_of,...input}),case_json:JSON.stringify({case_id:id,as_of,input})};}
function caseModal(index){const old=index==null?(S.dataset.rows.some(r=>r.case_json)?newSalesCase():{}):S.dataset.rows[index],c=caseContext(old),sales=Boolean(old.case_json),extra=Object.keys(old).filter(k=>!['case_id','user_input','context','criteria','actual_output','case_json','reference_output','as_of','instruction'].includes(k));S.caseEditing=old;openModal(index==null?'添加案例':'编辑案例',`<form id="case-form"><input type="hidden" name="index" value="${index??''}">${field('case_id','案例ID',old.case_id||'','text','',true)}${field('user_input','用户输入',old.user_input||'','textarea',sales?'同步到最后一条客户消息。':'',true)}${field('criteria','判定要求',parsed(old.criteria)?JSON.stringify(parsed(old.criteria),null,2):old.criteria||'','textarea','',true)}${sales?`${field('_instruction','本次任务要求',c.instruction||'','textarea')}<details class="details"><summary>沟通记录、客户背景与知识库资料</summary>${field('_history','沟通记录（JSON）',JSON.stringify(c.history||[],null,2),'textarea','修改最后一条客户消息，会同步上方用户输入。')}${field('_customer','客户背景（JSON）',JSON.stringify(c.customer||{},null,2),'textarea')}${field('_knowledge','知识库资料（JSON）',JSON.stringify(c.knowledge||[],null,2),'textarea')}<div class="decision-layout">${select('_intent','任务类型',[['analyze','分析'],['rewrite','话术改写']],c.intent||'analyze')}${field('_as_of','本例评测日期',c.as_of||'','date')}</div>${field('_previous','改写前结果（JSON）',c.previous?JSON.stringify(c.previous,null,2):'','textarea','改写任务需要保留改写前结果。')}</details>`:field('context','本例资料',old.context||'','textarea')}${field('actual_output','已有Agent回答（可选）',old.actual_output||'','textarea')}${extra.length?`<details class="details"><summary>其他案例字段</summary>${extra.map(k=>field(k,k,old[k]||'','textarea')).join('')}</details>`:''}${sales?'<p class="micro">请求数据由以上字段自动生成，保存后会核对一致性。</p>':''}${errorSlot()}<div class="tools"><button class="button primary" type="submit">保存案例</button>${index!=null?button('删除此案例','delete-case',false,`data-index="${index}"`):''}</div></form>`);}
function mapModal(){const cols=S.dataset.columns;openModal('匹配表格字段',`<form id="map-form">${['user_input','context','criteria','actual_output'].map(k=>select(k,{user_input:'用户输入来自哪一列',context:'资料来自哪一列',criteria:'判定要求来自哪一列',actual_output:'已有回答来自哪一列'}[k],[['','不使用'],...cols.map(x=>[x,x])],cols.includes(k)?k:'',['user_input','criteria'].includes(k))).join('')}${errorSlot()}<button class="button primary" type="submit">保存字段匹配</button></form>`);}
async function control(action){const input=$('#task-concurrency'),data={action};if(['resume','retry'].includes(action))data.concurrency=input?readConcurrency(input):taskConcurrency(S.task);await post(`/tasks/${S.task.id}/control`,data);await render();}
async function clickAction(el){const action=el.dataset.action,id=el.dataset.id;switch(action){case'skip-content':(workspaceReady()?app:authRoot).focus();break;case'retry-auth':await initializeAuth();break;case'toggle-password':{const input=document.getElementById(el.dataset.target);if(!input)break;const visible=input.type==='password';input.type=visible?'text':'password';el.textContent=visible?'隐藏':'显示';el.setAttribute('aria-pressed',String(visible));el.setAttribute('aria-label',(visible?'隐藏':'显示')+(input.labels?.[0]?.textContent.replace(/[ *（必填）]/g,'')||'密码'));break;}case'change-password':$('#account-menu').open=false;S.passwordScreen=true;renderAuthScreen(true);break;case'cancel-password':S.passwordScreen=false;await render();break;case'logout':await logout();break;case'close-modal':modal.close();break;case'upload':openModal('上传评测集',`<form id="upload-form">${field('name','数据集名称')}${field('file','数据文件','','file','支持CSV / XLSX / XLS，最大6MB。',true)}${errorSlot()}<button class="button primary" type="submit">上传并检查字段</button></form>`);break;case'new-dataset':openModal('创建数据集',`<form id="new-dataset-form">${field('name','名称','新数据集','text','',true)}${errorSlot()}<button class="button primary" type="submit">创建并编辑第一条案例</button></form>`);break;case'sales-preset':{const preset=await post('/presets/sales',{});draft({datasetId:preset.datasetId,agentId:''});toast('已导入50条合成案例，请配置自己的Agent接口。');go('/wizard/1');break;}case'use-dataset':draft({datasetId:id});go('/wizard/1');break;case'edit-case':caseModal(Number(el.dataset.index));break;case'add-case':caseModal(null);break;case'delete-case':openModal('删除案例',`<p>删除后本数据集中的案例无法恢复，历史评测快照会保留。</p>${button('确认删除','confirm-delete-case',false,`data-index="${el.dataset.index}"`)} ${button('取消','close-modal')}`);break;case'confirm-delete-case':{const rows=S.dataset.rows.filter((_,i)=>i!==Number(el.dataset.index));if(!rows.length)throw Error('数据集至少保留一条案例。');await api('/datasets/'+S.dataset.id,{method:'PUT',body:JSON.stringify({rows})});modal.close();await render();break;}case'map-columns':mapModal();break;case'rename-dataset':openModal('重命名',`<form id="rename-form">${field('name','名称',S.dataset.name,'text','',true)}${errorSlot()}<button class="button primary" type="submit">保存</button></form>`);break;case'copy-dataset':{const d=await post('/datasets',{name:S.dataset.name+' · 副本',rows:S.dataset.rows});go('/dataset/'+d.id);break;}case'delete-dataset':openModal('删除数据集',`<p>历史任务中的案例快照会保留。删除后无法恢复这个数据集。</p>${button('确认删除','confirm-delete-dataset',false,`data-id="${id}"`)} ${button('取消','close-modal')}`);break;case'confirm-delete-dataset':await api('/datasets/'+id,{method:'DELETE'});modal.close();go('/datasets');break;case'delete-config':openModal('删除配置',`<p>历史任务保留当时的配置快照。</p>${button('确认删除','confirm-delete-config',false,`data-id="${id}" data-kind="${el.dataset.kind}"`)} ${button('取消','close-modal')}`);break;case'confirm-delete-config':await api(`/${el.dataset.kind}/${id}`,{method:'DELETE'});modal.close();await render();break;case'import-curl':{const form=$('#agent-form');const x=await post('/import-curl',{curl:form.elements.curl.value});for(const[k,v]of Object.entries(x))form.elements[k].value=v;S.dirty=true;toast('已填入接口、Header和请求体，请核对后保存。');break;}case'preview':{const form=$('#wizard-config');if(!S.preflight?.ready)throw Error('请先完成配置检查。');const d=wizardData(form);d.concurrency=readConcurrency(form.elements.concurrency);draft(d);el.disabled=true;el.textContent='正在创建试跑…';try{const t=await post('/preview',{...d,datasetId:S.draft.datasetId});go('/task/'+t.id);}catch(err){formError(form,err);await wizardReady();}finally{el.textContent='先试跑第1条';}break;}case'check-config':await wizardReady();break;case'add-dimension':$('#dimension-rules').insertAdjacentHTML('beforeend',dimensionEditor({key:'dimension_'+(dimensionValues().length+1),label:'',max:0,rule:''}));dimensionTotal();S.dirty=true;break;case'remove-dimension':el.closest('.dimension-editor').remove();dimensionTotal();S.dirty=true;break;case'continue-trial':{const t=S.task;el.disabled=true;try{const next=await post('/tasks',{datasetId:t.snapshot.dataset.id,agentId:t.snapshot.agent?.id,rubricId:t.snapshot.rubric.id,mode:t.mode,answerColumn:t.answerColumn,concurrency:taskConcurrency(t),reuseTrialId:t.id,name:t.snapshot.dataset.name+' · 完整评测'});go('/task/'+next.id);}finally{el.disabled=false;}break;}case'control':await control(el.dataset.control);break;case'row-detail':{const row=S.task.rows.find(r=>r.id===el.dataset.row);openModal('案例执行详情',`${rowEvidence(row,S.task)}${fold('原始执行记录',`<pre class="trace">${e(JSON.stringify(row,null,2))}</pre>`)}`);break;}case'rescore':openModal('重新评分',`<form id="rescore-form">${select('rubricId','选用评分标准',S.boot.rubrics.filter(r=>r.enabled).map(r=>[r.id,`${r.name} · 版本${r.version}`]),S.task.snapshot.rubric.id)}${concurrencyField(taskConcurrency(S.task),{id:'rescore-concurrency'})}<p class="scoped-help">创建新任务，复用已有回答。原始评分和复核记录继续保留。</p>${errorSlot()}<button class="button primary" type="submit">创建重新评分任务</button></form>`);break;case'save-generated':{const d=await post('/datasets',{name:S.generated.name,rows:S.generated.rows});S.generated=null;go('/dataset/'+d.id);break;}}
}
document.addEventListener('click',async event=>{const account=$('#account-menu');if(account?.open&&!account.contains(event.target))account.open=false;const anchor=event.target.closest('a[href^="#"]');if(anchor&&S.dirty&&anchor.hash!==location.hash){if(!confirm('配置尚未保存，确定离开吗？')){event.preventDefault();return;}S.dirty=false;}const el=event.target.closest('[data-action]');if(!el)return;try{await clickAction(el);}catch(err){if(!err.silent)toast(err.message);}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='datasetId'){draft({datasetId:el.value});await fillDatasetPreview(el.value);const a=$('#edit-dataset-link');if(a)a.href='#/dataset/'+el.value;}if(el.id==='mode'){$('#agent-choice').hidden=el.value==='existing';$('#edit-agent-link').hidden=el.value==='existing';$('#existing-choice').hidden=el.value!=='existing';$('#agentId').required=el.value==='agent';$('#agentId').disabled=el.value==='existing';}if(el.id==='rubricId'&&$('#rubric-preview'))$('#rubric-preview').innerHTML=rubricPreview(S.boot.rubrics.find(r=>r.id===el.value));if(['agentId','rubricId','mode','answerColumn','concurrency'].includes(el.id)&&$('#wizard-config')){syncWizardConcurrency();draft(wizardData($('#wizard-config')));if(el.id==='agentId'){const a=$('#edit-agent-link');if(a)a.href='#/agent/'+el.value+'?return=wizard';}if(el.id==='rubricId'){const a=$('#edit-rubric-link');if(a)a.href='#/rubric/'+el.value+'?return=wizard';}await wizardReady();}if(el.id==='task-filter'){S.filter=el.value;$('#task-rows').innerHTML=taskRows(S.boot.tasks);}if(el.id==='case-filter')$('#case-rows').innerHTML=caseRows(S.task,el.value);if(el.name==='decision'&&$('#attribution-fields'))$('#attribution-fields').hidden=el.value==='normal';if(['user_input','_history'].includes(el.name))synchronizeCaseEditor(el.name);}catch(err){toast(err.message);}});
document.addEventListener('input',event=>{const el=event.target;if(el.closest('form[data-guard]'))S.dirty=true;if(el.dataset.dimension||['scoreMin','scoreMax'].includes(el.name))dimensionTotal();if(el.id==='task-search'){S.search=el.value;$('#task-rows').innerHTML=taskRows(S.boot.tasks);}if(['concurrency','task-concurrency','rescore-concurrency'].includes(el.id)){validateConcurrency(el);const hint=document.getElementById(el.id+'-hint');if(hint)hint.textContent=concurrencyHint(el.value,el.disabled,el.id==='task-concurrency');}if(['answerColumn','concurrency'].includes(el.id)&&$('#wizard-config')){draft(wizardData($('#wizard-config')));S.preflightKey='';S.preflight=null;$('#start-run').disabled=true;$('#wizard-config [data-action="preview"]').disabled=true;clearTimeout(S.checkTimer);S.checkTimer=setTimeout(wizardReady,350);}if(el.name==='user_input'&&$('#case-form'))synchronizeCaseEditor('user_input');});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(['login-form','password-form'].includes(form.id)){await submitAuth(form);return;}if(!workspaceReady()){renderAuthScreen();return;}const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;const d=formData(form);try{switch(form.getAttribute('id')){
case'wizard-data':draft({datasetId:d.datasetId});go('/wizard/2');break;
case'wizard-config':if(!S.preflight?.ready)throw Error('请先完成案例与配置检查。');d.concurrency=readConcurrency(form.elements.concurrency);draft(d);{const t=await post('/tasks',{...d,datasetId:S.draft.datasetId});go('/task/'+t.id);}break;
case'agent-form':case'rubric-form':{const kind=form.getAttribute('id')==='agent-form'?'agents':'rubrics';if(kind==='agents')d.concurrency=Number(d.concurrency);if(!d.id)delete d.id;for(const name of ['clearApiKey','doneRequired','enabled','thinkingEnabled'])if(form.elements[name])d[name]=form.elements[name].checked;if(kind==='rubrics'){d.dimensionRules=dimensionValues();if(d.dimensionRules.length){if(!d.dimensions.trim())d.dimensions=d.dimensionRules.map(x=>`${x.label}（${x.max}分）：${x.rule}`).join('；');const sum=d.dimensionRules.reduce((n,x)=>n+x.max,0),target=Number(d.scoreMax)-Number(d.scoreMin);if(Math.abs(sum-target)>0.0001)throw Error('各维度满分合计必须等于最高分减最低分。');if(new Set(d.dimensionRules.map(x=>x.key)).size!==d.dimensionRules.length)throw Error('评分维度的字段标识不能重复。');}}const back=d.back;delete d.back;delete d.curl;const saved=await post('/'+kind,d);S.dirty=false;draft({[kind==='agents'?'agentId':'rubricId']:saved.id});toast('配置已保存');go(back);break;}
case'upload-form':{const file=form.elements.file.files[0];if(file.size>6*1024*1024)throw Error('文件请控制在6MB以内。');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const saved=await post('/datasets',{name:d.name||file.name,fileName:file.name,file:btoa(binary)});modal.close();draft({datasetId:saved.id});go('/dataset/'+saved.id);toast('上传完成，请核对字段匹配。');break;}
case'new-dataset-form':{const saved=await post('/datasets',{name:d.name,rows:[{case_id:'C001',user_input:'请填写用户输入',context:'',criteria:'请填写明确判定要求',actual_output:''}]});modal.close();go('/dataset/'+saved.id);break;}
case'case-form':{const rows=structuredClone(S.dataset.rows),index=d.index,out=caseEditData(form,d);if(index==='')rows.push(out);else rows[Number(index)]=out;await api('/datasets/'+S.dataset.id,{method:'PUT',body:JSON.stringify({rows})});modal.close();await render();toast('案例与请求内容已保存');break;}
case'map-form':{const rows=S.dataset.rows.map(r=>({...r,...Object.fromEntries(Object.entries(d).map(([key,column])=>[key,column?r[column]||'':'']))}));await api('/datasets/'+S.dataset.id,{method:'PUT',body:JSON.stringify({rows})});modal.close();await render();toast('字段匹配已保存');break;}
case'rename-form':await api('/datasets/'+S.dataset.id,{method:'PUT',body:JSON.stringify(d)});modal.close();await render();break;
case'generate-form':{S.generated={...(await post('/generate',d)),name:d.name||'生成评测集'};$('#generated-preview').innerHTML=generatedHtml();break;}
case'review-form':{const taskId=S.task.id;if(d.decision==='normal'){d.issueType='';d.attribution='';d.attributionStatus='pending';}await post('/tasks/'+taskId+'/review',d);toast('复核与归因已保存');const fresh=await api('/tasks/'+taskId);const next=fresh.rows.find(r=>reviewable(r)&&!r.review?.decision&&(d.scope==='all'||needsReview(r)));if(next)go(`/review/${taskId}?row=${next.id}&scope=${d.scope}`);else go('/report/'+taskId);break;}
case'rescore-form':{const t=await post('/tasks/'+S.task.id+'/control',{action:'rescore',rubricId:d.rubricId,concurrency:readConcurrency(form.elements.concurrency)});modal.close();go('/task/'+t.id);break;}
}}catch(err){formError(form,err);}finally{if(submit)submit.disabled=false;if(form.id==='wizard-config'&&!S.preflight?.ready)submit.disabled=true;}});
document.addEventListener('invalid',event=>{let parent=event.target.parentElement;while(parent&&parent!==document.body){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}},true);
window.addEventListener('beforeunload',event=>{if(S.dirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',()=>{S.preflightKey='';render();});
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#account-menu')?.open)$('#account-menu').open=false;});
setInterval(async()=>{if(!workspaceReady())return;const currentHash=location.hash,{parts:p}=route();if(!['task','tasks'].includes(p[0]))return;try{if(p[0]==='tasks'){await refresh();if(workspaceReady()&&currentHash===location.hash&&$('#task-rows')){$('#task-rows').innerHTML=taskRows(S.boot.tasks);if($('#task-overview'))$('#task-overview').innerHTML=taskOverview(S.boot.tasks);}}else{const task=await api('/tasks/'+p[1]);if(!workspaceReady()||currentHash!==location.hash)return;if(!S.task||taskRenderKey(task)!==taskRenderKey(S.task)){const previousConcurrency=S.task?taskConcurrency(S.task):null,input=$('#task-concurrency'),editedValue=input?.value,focused=document.activeElement?.id;S.task=task;const filter=$('#case-filter')?.value||'all';app.innerHTML=taskPage(task);if($('#case-filter'))$('#case-filter').value=filter;if($('#case-rows'))$('#case-rows').innerHTML=caseRows(task,filter);const nextInput=$('#task-concurrency');if(nextInput&&editedValue!==undefined&&previousConcurrency===taskConcurrency(task)&&!nextInput.disabled){nextInput.value=editedValue;validateConcurrency(nextInput);$('#task-concurrency-hint').textContent=concurrencyHint(editedValue,false,true);}if(focused&&['task-concurrency','case-filter'].includes(focused))document.getElementById(focused)?.focus({preventScroll:true});}}}catch{/* next tick retries without discarding current page */}},1500);
